   found=sorted((case/'postProcessing'/name).glob('*/'+filename));c.require(len(found)==1,'One actual native force output file '+name);p=found[0];raw=e.text(p);c.require(('pressure' in raw and 'viscous' in raw) if columns==13 else ('Cd' in raw and 'Cl' in raw),'Actual native force/coeff header');a=c.force_rows(e,p,columns);expected=np.arange(first,first+count)*.05;selected=a[a[:,0]>(first-.5)*.05];c.require(selected.shape[0]==count and np.max(abs(selected[:,0]-expected))<=1e-10,'Exact actual physical-step force coverage');pair.append(selected);initial[name]=a[a[:,0]<(first-.5)*.05].tolist();paths.append(str(p))
